#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  TOTAL_STAGES=6
  ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
  cd "$ROOT_DIR"

  banner "Publicar comparações do Biblio"

  stage "Autenticar Wrangler"
  say "Este projeto requer Node.js 22 ou superior e uma conta Cloudflare."
  if ! command -v node >/dev/null 2>&1 || ! command -v npm >/dev/null 2>&1; then
    warn "Instale Node.js 22+ e npm e rode este wizard novamente."
    return 1
  fi
  node --version
  node -e 'if(Number(process.versions.node.split(".")[0])<22){console.error("Node.js 22 ou superior é necessário.");process.exit(1)}'
  if [[ ! -x node_modules/.bin/wrangler ]]; then
    step "Instalando as dependências travadas pelo projeto (npm ci)."
    npm ci
  fi
  open_url "https://dash.cloudflare.com/"
  step "No terminal, autentique o Wrangler na conta que hospedará o Worker."
  if ! npx wrangler whoami >/dev/null 2>&1; then
    npx wrangler login
  fi
  npx wrangler whoami
  pause "Confirme que o Wrangler mostra a conta Cloudflare desejada."

  stage "Criar ou reutilizar o banco D1"
  local database_id
  database_id="$(node -e 'const c=JSON.parse(require("fs").readFileSync("wrangler.jsonc","utf8")); console.log(c.d1_databases.find(x=>x.binding==="DB")?.database_id||"")')"
  if [[ "$database_id" =~ ^00000000-0000-0000-0000-000000000000$ || -z "$database_id" ]]; then
    say "O D1 biblio-results será criado na conta autenticada. Isso cria um recurso remoto."
    say "Cotas atuais do plano gratuito: 5 milhões de linhas lidas e 100 mil escritas por dia."
    if ! confirm "Criar o banco D1 biblio-results agora?"; then
      note "Nenhum recurso foi criado. Reexecute o wizard quando quiser continuar."
      return 0
    fi
    npx wrangler d1 create biblio-results
    ask database_id "Cole o database_id UUID exibido pelo Wrangler:"
    if [[ ! "$database_id" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]]; then
      warn "O valor não parece ser um UUID. O D1 existe, mas wrangler.jsonc não foi alterado."
      return 1
    fi
  else
    say "Reutilizando o database_id já configurado em wrangler.jsonc: $database_id"
    pause "Confirme que esse banco pertence à conta Cloudflare autenticada."
  fi
  BIBLIO_D1_ID="$database_id" node -e 'const fs=require("fs");const p="wrangler.jsonc";const c=JSON.parse(fs.readFileSync(p,"utf8"));const entries=c.d1_databases||[];const db=entries.find(x=>x.binding==="DB")||entries.find(x=>x.database_name==="biblio-results"&&x.database_id===process.env.BIBLIO_D1_ID);if(!db||db.database_name!=="biblio-results")throw Error("Binding D1 esperado não encontrado");db.binding="DB";db.database_id=process.env.BIBLIO_D1_ID;db.migrations_dir="worker/migrations";delete db.remote;c.d1_databases=[db,...entries.filter(x=>x!==db&&!(x.database_name==="biblio-results"&&x.database_id===process.env.BIBLIO_D1_ID))];fs.writeFileSync(p,JSON.stringify(c,null,2)+"\n")'
  say "Binding DB salvo e entradas duplicadas do mesmo banco removidas de wrangler.jsonc."
  node -e 'const c=JSON.parse(require("fs").readFileSync("wrangler.jsonc","utf8"));if(c.vars?.ALLOWED_ORIGIN!=="https://bibliooo.com.br")throw Error("ALLOWED_ORIGIN deve ser https://bibliooo.com.br");console.log("Origem permitida conferida: "+c.vars.ALLOWED_ORIGIN)'

  stage "Aplicar migrações remotas"
  say "O Wrangler aplicará as migrações pendentes 0001 e 0002 no D1 remoto."
  say "A migração cria tabelas e índices; não apaga resultados existentes."
  if ! confirm "Aplicar migrações em biblio-results na conta autenticada?"; then
    note "Migrações não aplicadas. É seguro reexecutar o wizard mais tarde."
    return 0
  fi
  npx wrangler d1 migrations apply biblio-results --remote

  stage "Publicar o Worker"
  say "O Worker ficará acessível publicamente. O Wrangler exibirá o endereço workers.dev."
  say "Workers Free inclui 100 mil requisições por dia; exceder cotas pode causar falhas."
  say "O wizard não contrata nem ativa plano pago."
  if ! confirm "Publicar o Worker biblio-results agora?"; then
    note "O D1 foi configurado, mas o Worker ainda não foi publicado."
    return 0
  fi
  npx wrangler deploy
  ask RESULTS_WORKER_URL "Cole a URL HTTPS exibida pelo Wrangler (sem /api):"
  if [[ ! "$RESULTS_WORKER_URL" =~ ^https://[A-Za-z0-9.-]+/?$ ]]; then
    warn "A URL deve ser HTTPS e não deve incluir caminho. O Worker foi publicado, mas site-config.js ficou inalterado."
    return 1
  fi

  stage "Conectar o site ao Worker"
  say "A URL será gravada em site-config.js e o site estático será gerado."
  if ! confirm "Ativar essa URL na configuração local do site?"; then
    note "O Worker está publicado; o site continuará sem enviar resultados até ativar a URL."
    return 0
  fi
  BIBLIO_RESULTS_URL="${RESULTS_WORKER_URL%/}/api" node -e 'const fs=require("fs");const p="site-config.js";let s=fs.readFileSync(p,"utf8");const value=JSON.stringify(process.env.BIBLIO_RESULTS_URL);if(!/resultsApiUrl:\s*"[^"]*"/.test(s))throw Error("resultsApiUrl não encontrado");s=s.replace(/resultsApiUrl:\s*"[^"]*"/,`resultsApiUrl: ${value}`);fs.writeFileSync(p,s)'
  npm run build
  pause "Build concluído. Confira site-config.js antes de publicar os arquivos estáticos."

  stage "Publicar o site estático e verificar"
  say "Publique os arquivos gerados pelo processo de hospedagem já usado pelo projeto."
  say "Depois abra o site, conclua um desafio e confira Estatísticas e a tela de resultado."
  say "No painel Cloudflare, confira requisições/erros do Worker e linhas lidas/escritas do D1."
  note "Este repositório não configura automaticamente o provedor de hospedagem estática."
  open_url "https://bibliooo.com.br/"
  pause "Quando a nova versão estiver publicada e você tiver conferido o jogo, pressione Enter."
  finish
}

run_wizard "$@"; exit
